import React, { useState } from "react";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { useAuth } from "@/hooks/useAuth";
import SidebarLayout from "@/components/SidebarLayout";
import PaymentHistoryCard from "@/components/settings/PaymentHistoryCard";
import UsageHistoryCard from "@/components/settings/UsageHistoryCard";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Switch } from "@/components/ui/switch";
import { Label } from "@/components/ui/label";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { toast } from "sonner";
import {
  Crown,
  Loader2,
  Zap,
  Check,
  ArrowRight,
  XCircle,
  CalendarClock,
  Sparkles,
  RefreshCw,
  CheckCircle2,
} from "lucide-react";
import { format } from "date-fns";

// ── Feature comparison data ─────────────────────────────────────────────────

type FVal = boolean | string;
const FEATURE_COMPARISON: {
  category: string;
  features: { name: string; free: FVal; starter: FVal; growth: FVal; agency: FVal }[];
}[] = [
  {
    category: "Core",
    features: [
      { name: "AI Resume Ranking", free: true, starter: true, growth: true, agency: true },
      { name: "Active Jobs", free: "1", starter: "5", growth: "20", agency: "∞" },
      { name: "CVs per month", free: "50", starter: "500", growth: "2,000", agency: "10,000" },
      { name: "Team Members", free: "1", starter: "∞", growth: "∞", agency: "∞" },
      { name: "Kanban Pipeline", free: true, starter: true, growth: true, agency: true },
      { name: "Custom Stages", free: false, starter: true, growth: true, agency: true },
      { name: "Custom Application Forms", free: false, starter: true, growth: true, agency: true },
      { name: "Knockout Questions", free: false, starter: true, growth: true, agency: true },
      { name: "Auto-Ack Emails", free: true, starter: true, growth: true, agency: true },
      { name: "CSV Import / Export", free: true, starter: true, growth: true, agency: true },
    ],
  },
  {
    category: "AI Features",
    features: [
      { name: "AI JD Generator", free: true, starter: true, growth: true, agency: true },
      { name: "AI Summary Cards", free: true, starter: true, growth: true, agency: true },
      { name: "AI Interview Questions", free: true, starter: true, growth: true, agency: true },
      { name: "AI Authenticity Check", free: false, starter: true, growth: true, agency: true },
      { name: "AI-Powered Search", free: false, starter: false, growth: true, agency: true },
      { name: "AI Rejection Emails", free: false, starter: true, growth: true, agency: true },
      { name: "Bias-Blind Mode", free: false, starter: true, growth: true, agency: true },
    ],
  },
  {
    category: "Collaboration",
    features: [
      { name: "Team Notes & @Mentions", free: false, starter: true, growth: true, agency: true },
      { name: "Evaluation Scorecards", free: false, starter: true, growth: true, agency: true },
      { name: "Candidate Tags", free: true, starter: true, growth: true, agency: true },
      { name: "Candidate Assignment", free: false, starter: true, growth: true, agency: true },
      { name: "Activity Feed", free: true, starter: true, growth: true, agency: true },
      { name: "Task Management", free: true, starter: true, growth: true, agency: true },
    ],
  },
  {
    category: "Career & Distribution",
    features: [
      { name: "Branded Career Page", free: false, starter: true, growth: true, agency: true },
      { name: "Google Jobs (JSON-LD)", free: false, starter: true, growth: true, agency: true },
      { name: "Indeed XML Feed", free: false, starter: false, growth: true, agency: true },
      { name: "Social Sharing", free: true, starter: true, growth: true, agency: true },
      { name: "Custom Domain", free: false, starter: false, growth: false, agency: true },
    ],
  },
  {
    category: "Communication",
    features: [
      { name: "Email Outreach", free: true, starter: true, growth: true, agency: true },
      { name: "WhatsApp Messaging", free: false, starter: false, growth: true, agency: true },
      { name: "Interview Scheduling", free: false, starter: true, growth: true, agency: true },
      { name: "Self-Serve Booking", free: false, starter: true, growth: true, agency: true },
    ],
  },
  {
    category: "Integrations & API",
    features: [
      { name: "REST API", free: false, starter: false, growth: true, agency: true },
      { name: "Webhooks", free: false, starter: false, growth: true, agency: true },
      { name: "Zapier", free: false, starter: false, growth: true, agency: true },
    ],
  },
  {
    category: "Agency",
    features: [
      { name: "White-Label Branding", free: false, starter: false, growth: false, agency: true },
      { name: "Client Portal", free: false, starter: false, growth: true, agency: true },
      { name: "Stage Automations", free: false, starter: false, growth: true, agency: true },
      { name: "Talent Pool", free: true, starter: true, growth: true, agency: true },
    ],
  },
  {
    category: "Support",
    features: [
      { name: "Email Support", free: true, starter: true, growth: true, agency: true },
      { name: "Priority Support", free: false, starter: true, growth: true, agency: true },
      { name: "Dedicated Account Mgr", free: false, starter: false, growth: false, agency: true },
    ],
  },
];

const PLAN_FEATURES: Record<string, string[]> = {
  default: [
    "All core ranking features",
    "Email resume ingestion",
    "Priority support",
    "Team access",
  ],
};

// ── Main page ────────────────────────────────────────────────────────────────

const Billing = () => {
  const { user, profile, refreshProfile } = useAuth();

  const [annualToggle, setAnnualToggle] = useState(false);
  const [buying, setBuying] = useState<string | null>(null);
  const [cancelling, setCancelling] = useState(false);
  const [downgrading, setDowngrading] = useState(false);
  const [confirmAction, setConfirmAction] = useState<{
    type: "upgrade" | "downgrade" | "cancel_subscription";
    planId?: string;
    planName?: string;
    price?: number;
  } | null>(null);

  const currentPlan = profile?.plan ?? "free";
  const isPaid = currentPlan !== "free";
  const subscriptionEndsAt = (profile as any)?.subscription_ends_at
    ? new Date((profile as any).subscription_ends_at)
    : null;
  const isExpired = subscriptionEndsAt ? subscriptionEndsAt < new Date() : false;
  const hasActiveSubscription = !!(profile as any)?.dodo_subscription_id;

  // Credits
  const subCredits = profile?.subscription_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const legacyCredits = profile?.credits ?? 0;
  const splitTotal = subCredits + bonusCredits;
  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;

  const { data: plans } = useQuery({
    queryKey: ["subscription_plans_active"],
    queryFn: async () => {
      const { data, error } = await supabase
        .from("plans")
        .select("*")
        .eq("active", true)
        .order("price");
      if (error) throw error;
      return data;
    },
  });

  // Filter by billing type when toggle changes
  const billingType = annualToggle ? "yearly" : "monthly";
  const allBillingTypes = plans?.map((p: any) => p.billing_type) ?? [];
  const hasAnnual = allBillingTypes.includes("yearly");
  const filteredPlans = hasAnnual
    ? plans?.filter((p: any) => p.billing_type === billingType)
    : plans;

  const popularIdx =
    filteredPlans && filteredPlans.length > 1
      ? Math.floor((filteredPlans.length - 1) / 2)
      : -1;

  const handleSubscribe = async (planId: string) => {
    if (!user) return;
    setBuying(planId);
    try {
      const { data, error } = await supabase.functions.invoke("create-dodo-checkout", {
        body: {
          plan_id: planId,
          return_url: `${window.location.origin}/payment/callback`,
        },
      });
      if (error) throw error;
      if (!data?.checkout_url) {
        toast.error(data?.error || "Failed to create checkout session");
        return;
      }
      window.location.href = data.checkout_url;
    } catch (err: unknown) {
      toast.error(err instanceof Error ? err.message : "Checkout failed");
    } finally {
      setBuying(null);
    }
  };

  const handleCancelSubscription = async () => {
    setCancelling(true);
    try {
      const { error } = await supabase.functions.invoke("cancel-dodo-subscription", {});
      if (error) throw error;
      toast.success("Auto-renewal cancelled. Your plan stays active until the billing period ends.");
      await refreshProfile();
      setConfirmAction(null);
    } catch (err: unknown) {
      toast.error("Failed to cancel: " + (err instanceof Error ? err.message : "Unknown error"));
    } finally {
      setCancelling(false);
    }
  };

  const handleDowngradeToFree = async () => {
    setDowngrading(true);
    try {
      if (hasActiveSubscription) {
        const { data, error: cancelError } = await supabase.functions.invoke(
          "cancel-dodo-subscription",
          {}
        );
        if (cancelError || data?.error) {
          toast.error(
            "Could not cancel subscription with payment provider. Please try again or contact support."
          );
          setDowngrading(false);
          return;
        }
      }
      const { error } = await supabase
        .from("profiles")
        .update({
          plan: "free",
          subscription_ends_at: null,
          dodo_subscription_id: null,
        } as any)
        .eq("user_id", user?.id);
      if (error) throw error;
      toast.success("Switched to Free plan. Your remaining credits are preserved.");
      await refreshProfile();
      setConfirmAction(null);
    } catch (err: unknown) {
      toast.error(
        "Failed to downgrade: " + (err instanceof Error ? err.message : "Unknown error")
      );
    } finally {
      setDowngrading(false);
    }
  };

  const handleConfirmedAction = () => {
    if (!confirmAction) return;
    if (confirmAction.type === "upgrade" && confirmAction.planId) {
      handleSubscribe(confirmAction.planId);
      setConfirmAction(null);
    } else if (confirmAction.type === "downgrade") {
      handleDowngradeToFree();
    } else if (confirmAction.type === "cancel_subscription") {
      handleCancelSubscription();
    }
  };

  return (
    <SidebarLayout>
      <main className="w-full px-6 sm:px-8 lg:px-10 py-8 max-w-5xl">
        {/* Page header */}
        <div className="mb-8">
          <h1 className="text-2xl font-semibold text-foreground tracking-tight">Billing & Plan</h1>
          <p className="text-sm text-muted-foreground mt-1">
            Manage your subscription and view usage history.
          </p>
        </div>

        <div className="space-y-8">
          {/* ── Current plan summary card ─────────────────────────────── */}
          <Card>
            <div className="px-6 pt-5 pb-5 flex items-start justify-between gap-4 flex-wrap">
              <div className="flex items-center gap-3">
                <div className="flex h-10 w-10 items-center justify-center rounded-lg bg-primary/10 shrink-0">
                  {isPaid ? (
                    <Crown className="h-5 w-5 text-primary" />
                  ) : (
                    <Zap className="h-5 w-5 text-muted-foreground" />
                  )}
                </div>
                <div>
                  <div className="flex items-center gap-2 flex-wrap">
                    <Badge
                      variant={isPaid ? "default" : "secondary"}
                      className="gap-1.5 capitalize text-sm px-2.5 py-0.5"
                    >
                      {isPaid ? <Crown className="h-3.5 w-3.5" /> : <Zap className="h-3.5 w-3.5" />}
                      {isPaid ? currentPlan : "Free"}
                    </Badge>
                    {subscriptionEndsAt && !isExpired && (
                      <Badge variant="secondary" className="gap-1 text-xs">
                        <CalendarClock className="h-3 w-3" />
                        {hasActiveSubscription
                          ? `Renews ${format(subscriptionEndsAt, "MMM d, yyyy")}`
                          : `Active until ${format(subscriptionEndsAt, "MMM d, yyyy")}`}
                      </Badge>
                    )}
                    {isExpired && (
                      <Badge variant="destructive" className="text-xs">Expired</Badge>
                    )}
                  </div>
                  <p className="text-sm text-muted-foreground mt-1">
                    {totalCredits.toLocaleString()} credits remaining
                    {subCredits > 0 && bonusCredits > 0 && (
                      <span className="text-xs ml-1">
                        ({subCredits.toLocaleString()} monthly + {bonusCredits.toLocaleString()} bonus)
                      </span>
                    )}
                  </p>
                </div>
              </div>

              <div className="flex items-center gap-2 shrink-0">
                {isPaid && hasActiveSubscription && !isExpired && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-8 text-xs gap-1.5 border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
                    onClick={() => setConfirmAction({ type: "cancel_subscription" })}
                    disabled={cancelling}
                  >
                    {cancelling ? (
                      <Loader2 className="h-3 w-3 animate-spin" />
                    ) : (
                      <XCircle className="h-3 w-3" />
                    )}
                    Cancel renewal
                  </Button>
                )}
                {isPaid && (
                  <Button
                    variant="outline"
                    size="sm"
                    className="h-8 text-xs gap-1.5 border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
                    onClick={() => setConfirmAction({ type: "downgrade" })}
                    disabled={downgrading}
                  >
                    {downgrading ? (
                      <Loader2 className="h-3 w-3 animate-spin" />
                    ) : (
                      <RefreshCw className="h-3 w-3" />
                    )}
                    Downgrade to Free
                  </Button>
                )}
              </div>
            </div>
          </Card>

          {/* ── Plan cards section ────────────────────────────────────── */}
          <section>
            <div className="flex items-center justify-between mb-5 flex-wrap gap-3">
              <div>
                <h2 className="text-lg font-semibold text-foreground">Choose Your Plan</h2>
                <p className="text-sm text-muted-foreground">
                  {isPaid
                    ? "Switch plans at any time. Upgrades take effect immediately."
                    : "Unlock more features and credits with a subscription."}
                </p>
              </div>
              {hasAnnual && (
                <div className="flex items-center gap-2">
                  <Label htmlFor="annual-toggle" className="text-sm text-muted-foreground">Monthly</Label>
                  <Switch
                    id="annual-toggle"
                    checked={annualToggle}
                    onCheckedChange={setAnnualToggle}
                  />
                  <Label htmlFor="annual-toggle" className="text-sm text-muted-foreground">
                    Annual
                    <Badge variant="secondary" className="ml-1.5 text-[10px] text-primary bg-primary/10 px-1 h-4">
                      Save 20%
                    </Badge>
                  </Label>
                </div>
              )}
            </div>

            <div
              className={`grid gap-4 ${
                filteredPlans && filteredPlans.length >= 3
                  ? "sm:grid-cols-2 lg:grid-cols-4"
                  : filteredPlans && filteredPlans.length === 2
                  ? "sm:grid-cols-3"
                  : "sm:grid-cols-2"
              }`}
            >
              {/* Free card */}
              <div
                className={`relative flex flex-col rounded-xl border p-5 transition-all ${
                  !isPaid
                    ? "border-primary/40 bg-primary/5 ring-1 ring-primary/20"
                    : "border-border bg-card hover:border-border/80"
                }`}
              >
                {!isPaid && (
                  <span className="absolute -top-2.5 left-3">
                    <Badge className="text-[10px] px-1.5 h-5 bg-primary text-primary-foreground gap-1">
                      <Check className="h-2.5 w-2.5" />
                      Current
                    </Badge>
                  </span>
                )}
                <div className="mb-3">
                  <p className="text-sm font-semibold text-foreground">Free</p>
                  <p className="text-[11px] text-muted-foreground mt-0.5">No commitment</p>
                </div>
                <div className="mb-4">
                  <div className="flex items-baseline gap-1">
                    <span className="text-2xl font-bold text-foreground">$0</span>
                    <span className="text-xs text-muted-foreground">/mo</span>
                  </div>
                </div>
                <ul className="space-y-1.5 flex-1 mb-5">
                  {["1 active job", "50 CVs per month", "Core ranking features", "Credits never expire"].map((f) => (
                    <li key={f} className="flex items-start gap-1.5 text-[11px] text-muted-foreground">
                      <Check className="h-3 w-3 text-primary mt-0.5 shrink-0" />
                      {f}
                    </li>
                  ))}
                </ul>
                {isPaid ? (
                  <Button
                    variant="outline"
                    size="sm"
                    className="w-full h-8 text-xs gap-1 border-destructive/30 text-destructive hover:bg-destructive/10 hover:text-destructive"
                    onClick={() => setConfirmAction({ type: "downgrade" })}
                    disabled={downgrading}
                  >
                    {downgrading ? <Loader2 className="h-3 w-3 animate-spin" /> : <RefreshCw className="h-3 w-3" />}
                    Switch to Free
                  </Button>
                ) : (
                  <div className="h-8 flex items-center justify-center">
                    <span className="text-[11px] text-muted-foreground">Your current plan</span>
                  </div>
                )}
              </div>

              {/* Subscription plan cards */}
              {filteredPlans?.map((plan: any, idx: number) => {
                const isCurrentPlan = currentPlan === plan.name;
                const isPopular = idx === popularIdx;
                const features: string[] = PLAN_FEATURES[plan.name] || PLAN_FEATURES["default"];

                return (
                  <div
                    key={plan.id}
                    className={`relative flex flex-col rounded-xl border p-5 transition-all ${
                      isCurrentPlan
                        ? "border-primary/40 bg-primary/5 ring-1 ring-primary/20"
                        : isPopular
                        ? "border-primary/25 bg-card shadow-sm"
                        : "border-border bg-card hover:border-border/80"
                    }`}
                  >
                    {isPopular && !isCurrentPlan && (
                      <span className="absolute -top-2.5 left-3">
                        <Badge className="text-[10px] px-1.5 h-5 bg-primary text-primary-foreground gap-1">
                          <Sparkles className="h-2.5 w-2.5" />
                          Popular
                        </Badge>
                      </span>
                    )}
                    {isCurrentPlan && (
                      <span className="absolute -top-2.5 left-3">
                        <Badge className="text-[10px] px-1.5 h-5 bg-primary text-primary-foreground gap-1">
                          <Check className="h-2.5 w-2.5" />
                          Current
                        </Badge>
                      </span>
                    )}

                    <div className="mb-3">
                      <p className="text-sm font-semibold text-foreground capitalize">{plan.name}</p>
                      <p className="text-[11px] text-muted-foreground mt-0.5 capitalize">
                        {plan.billing_type} • {plan.credits} credits
                      </p>
                    </div>

                    <div className="mb-4">
                      <div className="flex items-baseline gap-1">
                        <span className="text-2xl font-bold text-foreground">${plan.price}</span>
                        <span className="text-xs text-muted-foreground">
                          /{plan.billing_type === "yearly" ? "yr" : "mo"}
                        </span>
                      </div>
                    </div>

                    <ul className="space-y-1.5 flex-1 mb-5">
                      {features.map((f) => (
                        <li key={f} className="flex items-start gap-1.5 text-[11px] text-muted-foreground">
                          <Check className="h-3 w-3 text-primary mt-0.5 shrink-0" />
                          {f}
                        </li>
                      ))}
                    </ul>

                    {isCurrentPlan ? (
                      <div className="h-8 flex items-center justify-center">
                        <span className="text-[11px] text-muted-foreground">Your current plan</span>
                      </div>
                    ) : (
                      <Button
                        size="sm"
                        className="w-full h-8 text-xs gap-1"
                        onClick={() =>
                          setConfirmAction({
                            type: "upgrade",
                            planId: plan.id,
                            planName: plan.name,
                            price: plan.price,
                          })
                        }
                        disabled={buying === plan.id}
                      >
                        {buying === plan.id ? (
                          <Loader2 className="h-3.5 w-3.5 animate-spin" />
                        ) : (
                          <>
                            Subscribe
                            <ArrowRight className="h-3 w-3" />
                          </>
                        )}
                      </Button>
                    )}
                  </div>
                );
              })}

              {(!plans || plans.length === 0) && (
                <div className="col-span-full text-center py-8 text-sm text-muted-foreground">
                  No subscription plans available right now.
                </div>
              )}
            </div>
          </section>

          {/* ── Feature comparison table ──────────────────────────────── */}
          <section>
            <h2 className="text-lg font-semibold text-foreground mb-1">Compare All Features</h2>
            <p className="text-sm text-muted-foreground mb-4">Everything included in each plan.</p>

            <Card>
              <CardContent className="p-0 overflow-x-auto">
                <table className="w-full text-left">
                  <thead>
                    <tr className="border-b border-border">
                      <th className="px-6 py-3 text-xs font-medium text-muted-foreground w-[45%]">Feature</th>
                      <th className="px-4 py-3 text-xs font-medium text-muted-foreground text-center">Free</th>
                      <th className="px-4 py-3 text-xs font-medium text-muted-foreground text-center">Starter</th>
                      <th className="px-4 py-3 text-xs font-medium text-primary text-center">Growth</th>
                      <th className="px-4 py-3 text-xs font-medium text-muted-foreground text-center">Agency</th>
                    </tr>
                  </thead>
                  <tbody>
                    {FEATURE_COMPARISON.map((cat, ci) => (
                      <React.Fragment key={ci}>
                        <tr>
                          <td
                            colSpan={5}
                            className="px-6 pt-5 pb-2 text-[10px] font-bold uppercase tracking-wider text-muted-foreground/60"
                          >
                            {cat.category}
                          </td>
                        </tr>
                        {cat.features.map((f, fi) => (
                          <tr key={fi} className="border-b border-border/40 last:border-0 hover:bg-muted/30 transition-colors">
                            <td className="px-6 py-2.5 text-sm text-foreground">{f.name}</td>
                            {([f.free, f.starter, f.growth, f.agency] as FVal[]).map((v, vi) => (
                              <td key={vi} className="px-4 py-2.5 text-center">
                                {v === true ? (
                                  <CheckCircle2 className="h-4 w-4 text-emerald-500 mx-auto" />
                                ) : v === false ? (
                                  <span className="text-muted-foreground/30 text-lg leading-none">—</span>
                                ) : (
                                  <span className="text-xs font-semibold text-foreground">{v}</span>
                                )}
                              </td>
                            ))}
                          </tr>
                        ))}
                      </React.Fragment>
                    ))}
                  </tbody>
                </table>
              </CardContent>
            </Card>

            <p className="text-[11px] text-muted-foreground text-center mt-3">
              All plans include unlimited users. Subscriptions auto-renew. Cancel anytime.
            </p>
          </section>

          {/* ── Payment + Usage history ───────────────────────────────── */}
          <PaymentHistoryCard />
          <UsageHistoryCard />
        </div>
      </main>

      {/* ── Confirm dialog ───────────────────────────────────────────── */}
      <AlertDialog
        open={confirmAction !== null}
        onOpenChange={(o) => !o && setConfirmAction(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>
              {confirmAction?.type === "upgrade"
                ? `Subscribe to ${confirmAction.planName}?`
                : confirmAction?.type === "cancel_subscription"
                ? "Cancel Auto-Renewal?"
                : "Switch to Free?"}
            </AlertDialogTitle>
            <AlertDialogDescription asChild>
              <div>
                {confirmAction?.type === "upgrade" ? (
                  <span>
                    You'll be redirected to our secure checkout to complete payment of{" "}
                    <strong className="text-foreground font-semibold">${confirmAction.price}</strong>.
                    Your subscription will auto-renew each billing period.
                  </span>
                ) : confirmAction?.type === "cancel_subscription" ? (
                  <span>
                    Your plan stays active until the end of your current billing period. After
                    that you'll move to Free. Your remaining credits are preserved.
                  </span>
                ) : (
                  <span>
                    You'll switch to the Free plan. Your remaining credits are preserved.
                    {hasActiveSubscription && " Your active subscription will also be cancelled."}
                  </span>
                )}
              </div>
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep Current Plan</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleConfirmedAction}
              disabled={downgrading || cancelling}
              className={
                confirmAction?.type !== "upgrade"
                  ? "bg-destructive text-destructive-foreground hover:bg-destructive/90"
                  : ""
              }
            >
              {(downgrading || cancelling) && (
                <Loader2 className="h-4 w-4 animate-spin mr-1.5" />
              )}
              {confirmAction?.type === "upgrade"
                ? "Proceed to Payment"
                : confirmAction?.type === "cancel_subscription"
                ? "Cancel Auto-Renewal"
                : "Confirm Downgrade"}
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </SidebarLayout>
  );
};

export default Billing;

import { useState, useEffect } from "react";
import { useAuth } from "@/hooks/useAuth";
import { Card, CardContent } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/badge";
import { Tooltip, TooltipContent, TooltipProvider, TooltipTrigger } from "@/components/ui/tooltip";
import { User, Crown, Zap, ArrowUpRight, AlertTriangle } from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";
import { useNavigate } from "react-router-dom";

type CreditType = { key: string; color: string; label: string; count: number; desc: string };

const CREDIT_TYPES: Omit<CreditType, "count">[] = [
  { key: "monthly", color: "hsl(var(--rk-primary))", label: "Monthly", desc: "From your subscription — consumed first." },
  { key: "bonus", color: "hsl(var(--rk-score-education))", label: "Bonus", desc: "Bonus credits — never expire." },
];

const AccountInfoCard = ({ showHero = true }: { showHero?: boolean }) => {
  const { user, profile } = useAuth();
  const navigate = useNavigate();
  const [animated, setAnimated] = useState(false);

  useEffect(() => {
    const t = setTimeout(() => setAnimated(true), 50);
    return () => clearTimeout(t);
  }, []);

  const subCredits = profile?.subscription_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const splitTotal = subCredits + bonusCredits;
  const legacyCredits = profile?.credits ?? 0;
  const total = splitTotal > 0 ? splitTotal : legacyCredits;
  const showLegacy = splitTotal === 0 && legacyCredits > 0;

  const plan = profile?.plan ?? "free";
  const isPaid = plan !== "free";
  const isLow = total < 3;

  // Build credit types with counts
  const creditTypes: CreditType[] = showLegacy
    ? [{ key: "legacy", color: "hsl(var(--rk-primary))", label: "Available", count: legacyCredits, desc: "Your available credits." }]
    : CREDIT_TYPES.map((t) => ({
        ...t,
        count: t.key === "monthly" ? subCredits : bonusCredits,
      }));

  const activeSegments = creditTypes.filter((t) => t.count > 0);
  const activeSource = subCredits > 0 ? "monthly" : bonusCredits > 0 ? "bonus" : null;

  return (
    <Card className="overflow-hidden">
      {/* Hero banner — only on profile page */}
      {showHero && (
        <div className="relative bg-gradient-to-br from-primary/10 via-primary/5 to-transparent dark:from-primary/20 dark:via-primary/10 px-6 pt-6 pb-8">
          <div className="flex items-start justify-between">
            <div className="flex items-center gap-3">
              <div className="flex h-12 w-12 items-center justify-center rounded-full bg-primary/15 ring-2 ring-primary/20">
                <User className="h-6 w-6 text-primary" />
              </div>
              <div>
                <p className="text-sm font-medium text-muted-foreground">Welcome back</p>
                <p className="text-base font-semibold text-foreground truncate max-w-[220px] sm:max-w-none">
                  {user?.email}
                </p>
              </div>
            </div>
            <div className="flex items-center gap-2">
              <Badge variant={isPaid ? "default" : "secondary"} className="gap-1.5 capitalize">
                {isPaid ? <Crown className="h-3 w-3" /> : <Zap className="h-3 w-3" />}
                {isPaid ? plan : "Free"}
              </Badge>
              <Button
                variant="ghost"
                size="sm"
                className="h-7 gap-1 text-xs text-primary hover:text-primary"
                onClick={() => navigate("/billing")}
              >
                <ArrowUpRight className="h-3 w-3" />
                {isPaid ? "Manage" : "Upgrade"}
              </Button>
            </div>
          </div>
        </div>
      )}

      {/* Plan bar — shown when hero is hidden (billing page) */}
      {!showHero && (
        <div className="px-6 pt-5 pb-0 flex items-center justify-between">
          <div className="flex items-center gap-2">
            <Badge variant={isPaid ? "default" : "secondary"} className="gap-1.5 capitalize">
              {isPaid ? <Crown className="h-3 w-3" /> : <Zap className="h-3 w-3" />}
              {isPaid ? plan : "Free"}
            </Badge>
          </div>
          <Button
            variant="outline"
            size="sm"
            className="h-7 gap-1.5 text-xs"
            onClick={() => navigate("/billing")}
          >
            <ArrowUpRight className="h-3 w-3" />
            {isPaid ? "Manage Plan" : "Upgrade"}
          </Button>
        </div>
      )}

      {/* Credits section */}
      <CardContent className="px-6 py-5 space-y-3">
        {!profile ? (
          <div className="space-y-3">
            <div className="flex items-center justify-between">
              <Skeleton className="h-4 w-16" />
              <Skeleton className="h-7 w-24" />
            </div>
            <Skeleton className="h-2 w-full rounded-full" />
            <div className="flex gap-4">
              <Skeleton className="h-3 w-20" />
              <Skeleton className="h-3 w-20" />
            </div>
          </div>
        ) : (
        <>
        {/* Header row */}
        <div className="flex items-center justify-between">
          <span className="text-sm font-semibold text-foreground">Credits</span>
          <span className="text-sm font-semibold text-foreground tabular-nums">
            {total}
            <span className="text-muted-foreground font-normal ml-1">left</span>
          </span>
        </div>

        {/* Segmented bar */}
        <TooltipProvider delayDuration={80}>
          <div className="space-y-2">
            {/* Bar track */}
            <div className="relative h-2 w-full rounded-full bg-muted">
              <div className="absolute inset-0 flex gap-[2px]">
                {activeSegments.map((seg, i) => {
                  const pct = (seg.count / total) * 100;
                  return (
                    <Tooltip key={seg.key}>
                      <TooltipTrigger asChild>
                        <div
                          className="h-full cursor-pointer transition-all duration-500 ease-out hover:brightness-110"
                          style={{
                            width: animated ? `${pct}%` : "0%",
                            backgroundColor: seg.color,
                            transitionDelay: `${i * 100}ms`,
                            borderRadius:
                              activeSegments.length === 1
                                ? "9999px"
                                : i === 0
                                ? "9999px 0 0 9999px"
                                : i === activeSegments.length - 1
                                ? "0 9999px 9999px 0"
                                : "0",
                          }}
                        />
                      </TooltipTrigger>
                      <TooltipContent side="top" className="max-w-[220px] p-3 space-y-1">
                        <div className="flex items-center gap-2">
                          <span className="inline-block w-2.5 h-2.5 rounded-full shrink-0" style={{ backgroundColor: seg.color }} />
                          <span className="font-semibold text-sm">{seg.label}</span>
                        </div>
                        <p className="text-base font-bold tabular-nums">{seg.count} credits</p>
                        <p className="text-xs text-muted-foreground leading-relaxed">{seg.desc}</p>
                      </TooltipContent>
                    </Tooltip>
                  );
                })}
              </div>
            </div>

            {/* Always-visible legend */}
            <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
              {creditTypes.map((ct) => (
                <span
                  key={ct.key}
                  className={`flex items-center gap-1.5 text-xs ${ct.count > 0 ? "text-muted-foreground" : "text-muted-foreground/40"}`}
                >
                  <span
                    className="inline-block w-2 h-2 rounded-full shrink-0"
                    style={{ backgroundColor: ct.color, opacity: ct.count > 0 ? 1 : 0.3 }}
                  />
                  {ct.label} ({ct.count})
                </span>
              ))}
              {total === 0 && (
                <span className="flex items-center gap-1.5 text-xs text-destructive">
                  <AlertTriangle className="h-3 w-3" />
                  No credits remaining
                </span>
              )}
            </div>

            {/* Active source note */}
            {activeSource && !showLegacy && (
              <p className="text-[11px] text-muted-foreground">
                Using {activeSource} credits first.
              </p>
            )}
          </div>
        </TooltipProvider>

        {isLow && total > 0 && (
          <div className="rounded-md bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive flex items-center gap-1.5">
            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
            Low credits — upgrade to keep ranking resumes.
          </div>
        )}
        {total === 0 && (
          <div className="rounded-md bg-destructive/10 px-3 py-2 text-xs font-medium text-destructive flex items-center gap-1.5">
            <AlertTriangle className="h-3.5 w-3.5 shrink-0" />
            No credits left — upgrade your plan to continue ranking.
          </div>
        )}
        </>
        )}
      </CardContent>
    </Card>
  );
};

export default AccountInfoCard;

import React from "react";
import { useAuth } from "@/hooks/useAuth";
import { useNavigate } from "react-router-dom";
import { Popover, PopoverContent, PopoverTrigger } from "@/components/ui/popover";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";
import { Database, ChevronDown, AlertTriangle, Zap, Gift, ExternalLink } from "lucide-react";
import { cn } from "@/lib/utils";
import { useState } from "react";

const WalletDropdown = () => {
  const { profile } = useAuth();
  const navigate = useNavigate();
  const [open, setOpen] = useState(false);

  const subCredits = profile?.subscription_credits ?? 0;
  const bonusCredits = profile?.bonus_credits ?? 0;
  const splitTotal = subCredits + bonusCredits;
  const legacyCredits = profile?.credits ?? 0;
  const totalCredits = splitTotal > 0 ? splitTotal : legacyCredits;
  const isLowCredits = totalCredits < 3;
  const hasSplitCredits = splitTotal > 0;

  return (
    <Popover open={open} onOpenChange={setOpen}>
      <PopoverTrigger asChild>
        <button
          className={`group inline-flex items-center gap-1.5 rounded-lg px-3 py-1.5 outline-none focus-visible:ring-2 focus-visible:ring-offset-1 border transition-all ${
            isLowCredits
              ? "border-destructive/40 text-destructive hover:border-destructive hover:bg-destructive/5 focus-visible:ring-destructive"
              : "border-border bg-muted/50 text-foreground hover:border-foreground/30 hover:bg-muted focus-visible:ring-ring"
          }`}
        >
          {isLowCredits ? (
            <AlertTriangle className="h-4 w-4 shrink-0" />
          ) : (
            <Database className="h-4 w-4 shrink-0 text-primary" />
          )}
          <span className="text-sm font-semibold tabular-nums">{totalCredits.toLocaleString()}</span>
          <span className="text-[11px] font-medium text-muted-foreground">Credits</span>
          <ChevronDown className={`h-3 w-3 text-muted-foreground transition-transform ${open ? "rotate-180" : ""}`} />
        </button>
      </PopoverTrigger>

      <PopoverContent align="end" className="w-64 p-0">
        {/* Balance header */}
        <div className="px-4 pt-4 pb-3">
          <p className="text-[10px] font-semibold text-muted-foreground uppercase tracking-widest">Credit Balance</p>
          <div className="flex items-baseline gap-2 mt-1">
            <span className="text-3xl font-bold tabular-nums text-foreground leading-none">
              {totalCredits.toLocaleString()}
            </span>
            <span className="text-xs text-muted-foreground font-medium">credits left</span>
          </div>
        </div>

        {/* Progress bar */}
        {hasSplitCredits && totalCredits > 0 && (
          <div className="px-4 pb-3">
            <div className="h-2 rounded-full bg-muted overflow-hidden flex">
              {[
                { label: "Monthly", value: subCredits, color: "bg-primary" },
                { label: "Bonus", value: bonusCredits, color: "bg-amber-400" },
              ].map((seg) =>
                seg.value > 0 ? (
                  <div
                    key={seg.label}
                    className={cn("h-full first:rounded-l-full last:rounded-r-full", seg.color)}
                    style={{ width: `${(seg.value / totalCredits) * 100}%` }}
                  />
                ) : null
              )}
            </div>
            <div className="flex items-center gap-3 mt-2">
              {[
                { label: "Monthly", value: subCredits, color: "bg-primary" },
                { label: "Bonus", value: bonusCredits, color: "bg-amber-400" },
              ].map((seg) =>
                seg.value > 0 ? (
                  <div key={seg.label} className="flex items-center gap-1.5">
                    <span className={cn("h-2 w-2 rounded-full", seg.color)} />
                    <span className="text-[10px] text-muted-foreground">
                      {seg.label} ({seg.value.toLocaleString()})
                    </span>
                  </div>
                ) : null
              )}
            </div>
          </div>
        )}

        <Separator />

        {/* Breakdown rows */}
        {hasSplitCredits && (
          <div className="px-4 py-3 space-y-2.5">
            <CreditRow icon={Zap} label="Subscription" value={subCredits} color="text-primary" />
            <CreditRow icon={Gift} label="Bonus" value={bonusCredits} color="text-amber-500" />
          </div>
        )}

        {/* Low credits warning */}
        {isLowCredits && (
          <>
            <Separator />
            <div className="px-4 py-2.5 bg-destructive/5">
              <p className="text-xs text-destructive font-medium">
                Running low — upgrade to keep ranking.
              </p>
            </div>
          </>
        )}

        {/* Actions */}
        <Separator />
        <div className="p-2">
          <Button
            variant="outline"
            className="w-full gap-2"
            onClick={() => { setOpen(false); navigate("/billing"); }}
          >
            <ExternalLink className="h-4 w-4" />
            View Billing
          </Button>
        </div>
      </PopoverContent>
    </Popover>
  );
};

function CreditRow({
  icon: Icon,
  label,
  value,
  color,
}: {
  icon: React.ComponentType<{ className?: string }>;
  label: string;
  value: number;
  color: string;
}) {
  return (
    <div className="flex items-center justify-between">
      <div className="flex items-center gap-2">
        <Icon className={`h-3.5 w-3.5 ${color}`} />
        <span className="text-xs text-muted-foreground">{label}</span>
      </div>
      <span className="text-xs font-semibold tabular-nums text-foreground">{value.toLocaleString()}</span>
    </div>
  );
}

export default React.memo(WalletDropdown);

